/* Offline lessons in real Chromium: the service worker generated by PwaAssets, Cache Storage, and the browser's real offline mode.
 * Run: NODE_PATH=$(npm root -g) node tests/browser/offline.spec.cjs   (needs ffmpeg) */
const http = require('http');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { execFileSync } = require('child_process');
const { chromium } = require('playwright');

const root = path.resolve(__dirname, '../..');
const read = (f) => fs.readFileSync(path.join(root, f));
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'nk-off-'));
const videoPath = path.join(tmp, 'v.webm');
execFileSync('ffmpeg', ['-v', 'error', '-f', 'lavfi', '-i', 'testsrc=size=320x180:rate=15:duration=30', '-c:v', 'libvpx', '-b:v', '200k', '-an', videoPath]);
const video = fs.readFileSync(videoPath);
const swSource = execFileSync('php', ['-r', `require '${root}/src/Pwa/PwaAssets.php'; echo Nimikh\\LMS\\Pwa\\PwaAssets::serviceWorker(['version'=>'t1','offline_url'=>'/nimikh-offline/','precache'=>[],'static_prefixes'=>['/js/','/css/']]);`]).toString();

const DEVICE_RE = /^[a-f0-9]{32}$/;
const st = { grants: [], releases: [], attempts: [], live: null, mediaStatus: 200, grantStatus: 200, playerHits: 0 };
const lessonPlayer = () => ({
  lesson_id: 7, title: 'Demo', duration: 30, source: { type: 'hls', url: 'https://cdn.invalid/expired.m3u8', expires: 1 }, captions: [], resume_second: 0, furthest: 0, percent: 0, completed: false,
  gate: 8, watermark: 'rafi@example.com', settings: { max_rate: 2, heartbeat_interval: 10 },
  interactions: [{ id: 1, at_second: 8, required: true, allow_retry: true, points: 1, rewind_to_second: null, resolved: false, question: { stem: 'What does SUM do?', options: ['Adds', 'Multiplies', 'Counts'], lang: 'en' } }],
});
const i18n = { quickCheck: 'Quick check!', continue: 'Continue', submit: 'Check answer', skip: 'Skip', correct: 'Correct', tryAgain: 'Not quite.', rewind: 'again', answerIs: 'The correct answer is highlighted.', mustAnswer: 'Answer the question to continue', speedCapped: 'cap', completed: 'Lesson complete', loadError: 'err', saving: 'saved', notes: 'My notes', notePlaceholder: 'note', addNoteAt: 'Add note at', noteDelete: 'Delete note', notesEmpty: 'No notes', noteError: 'err', offlineCopy: 'Playing your offline copy', offlineSaved: 'Answer saved. We will check it when you are back online.' };
const offI18n = { download: 'Download for offline', downloading: 'Downloading… %d%%', ready: 'Available offline until %s', remove: 'Remove download', expired: 'expired', noSupport: 'No support', noSpace: 'No space', failed: 'The download failed.', none: 'No lessons downloaded yet.', note: 'Downloaded lessons expire.' };

const page = `<!doctype html><meta charset=utf-8><title>Lesson</title><link rel=stylesheet href=/css/tokens.css><link rel=stylesheet href=/css/player.css>
<div class="nk-player" data-lesson="7" data-mode="learner"></div><div class="nk-offline" data-lesson="7"></div><section class="nk-downloads"></section>
<script>window.NimikhPlayer=${JSON.stringify({ restUrl: '/wp-json/nimikh/v1', nonce: 'n', hlsSrc: '', i18n })};window.NimikhOffline=${JSON.stringify({ restUrl: '/wp-json/nimikh/v1', nonce: 'n', i18n: offI18n })};
navigator.serviceWorker.register('/nimikh-sw.js',{scope:'/'});</script>
<script src=/js/player.js></script><script src=/js/offline.js></script>`;

const server = http.createServer((req, res) => {
  const u = req.url.split('?')[0];
  const send = (code, type, body, h) => { res.writeHead(code, Object.assign({ 'Content-Type': type }, h || {})); res.end(body); };
  const json = (o, code) => send(code || 200, 'application/json', JSON.stringify(o));
  if (u === '/lesson/') { return send(200, 'text/html', page); }
  if (u === '/nimikh-sw.js') { return send(200, 'application/javascript', swSource, { 'Service-Worker-Allowed': '/', 'Cache-Control': 'no-cache' }); }
  if (u === '/nimikh-offline/') { return send(200, 'text/html', '<h1>You are offline</h1>'); }
  if (u.startsWith('/js/')) { return send(200, 'text/javascript', read('assets/js/' + u.slice(4))); }
  if (u.startsWith('/css/')) { return send(200, 'text/css', read('assets/css/' + u.slice(5))); }
  if (u === '/media/lesson7.webm') {
    if (st.mediaStatus !== 200) { return send(st.mediaStatus, 'text/plain', 'boom'); }
    return send(200, 'video/webm', video, { 'Content-Length': video.length, 'Accept-Ranges': 'bytes' });
  }
  let body = ''; req.on('data', (c) => (body += c)); req.on('end', () => {
    const data = body ? JSON.parse(body) : {};
    if (u === '/wp-json/nimikh/v1/lessons/7/offline' && req.method === 'POST') {
      st.grants.push(data);
      if (st.grantStatus === 409) { return json({ code: 'nimikh_offline_limit', message: 'You have reached the limit of downloaded lessons.' }, 409); }
      return json({ allow: true, url: '/media/lesson7.webm', expires_at: Math.floor(Date.now() / 1000) + 7 * 86400, title: 'Demo lesson', days: 7 });
    }
    if (u === '/wp-json/nimikh/v1/lessons/7/offline' && req.method === 'DELETE') { st.releases.push(data); return json({ released: true }); }
    if (u === '/wp-json/nimikh/v1/me/offline') { return json({ licenses: st.live === null ? [{ lesson_id: 7, expires_at: Math.floor(Date.now() / 1000) + 86400 }] : st.live }); }
    if (u === '/wp-json/nimikh/v1/lessons/7/player') { st.playerHits++; return json(lessonPlayer()); }
    if (u.startsWith('/wp-json/nimikh/v1/lessons/7/heartbeat')) { return json({ ok: true, rejected: false, furthest: 8, percent: 0, completed: false, gate: 8 }); }
    if (u === '/wp-json/nimikh/v1/interactions/1/attempt') { st.attempts.push(data); return json({ correct: true, resolved: true, explanation: 'Adds numbers', lesson_completed: false }); }
    res.statusCode = 404; res.end();
  });
});

let pass = 0, fail = 0;
const ok = (c, l, x) => { if (c) { pass++; console.log('  ok   ' + l); } else { fail++; console.log('  FAIL ' + l + (x ? ' ' + x : '')); } };
const cacheKeys = (p) => p.evaluate(() => caches.open('nimikh-offline').then((c) => c.keys()).then((k) => k.map((r) => r.url.replace(location.origin, ''))));

(async () => {
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  const origin = 'http://127.0.0.1:' + server.address().port;
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ serviceWorkers: 'allow' });
  const page1 = await ctx.newPage();
  const errors = []; page1.on('pageerror', (e) => errors.push(e.message));

  console.log('== download');
  await page1.goto(origin + '/lesson/');
  await page1.evaluate(() => navigator.serviceWorker.ready);
  await page1.waitForFunction(() => !!navigator.serviceWorker.controller, null, { timeout: 8000 });
  ok(await page1.locator('.nk-offline button').innerText() === 'Download for offline', 'the lesson offers a download button');
  await page1.click('.nk-offline button');
  await page1.waitForFunction(() => /Available offline until/.test(document.querySelector('.nk-offline__text').textContent), null, { timeout: 15000 });
  const keys = await cacheKeys(page1);
  ok(keys.includes('/nimikh-offline-media/7/video.mp4') && keys.includes('/nimikh-offline-media/7/license.json') && keys.includes('/nimikh-offline-media/7/player.json'), 'video, licence and player data are stored', JSON.stringify(keys));
  ok(keys.includes('/lesson/') && keys.some((k) => k.startsWith('/js/player.js')), 'the lesson page and its scripts are stored');
  ok(st.grants.length === 1 && DEVICE_RE.test(st.grants[0].device), 'the server was asked for a licence with a 32-hex device id');
  const lic = await page1.evaluate(() => caches.open('nimikh-offline').then((c) => c.match(location.origin + '/nimikh-offline-media/7/license.json')).then((r) => r.json()));
  ok(lic.lesson_id === 7 && lic.expires_at * 1000 > Date.now() + 6 * 86400000, 'the licence expires in about 7 days');
  const vsize = await page1.evaluate(() => caches.open('nimikh-offline').then((c) => c.match(location.origin + '/nimikh-offline-media/7/video.mp4')).then((r) => r.blob()).then((b) => b.size));
  ok(vsize === video.length, 'the whole video was stored (' + vsize + ' bytes)');
  ok(await page1.locator('.nk-offline button').innerText() === 'Remove download', 'the button now offers removal');
  await page1.reload();
  await page1.waitForSelector('.nk-downloads li');
  ok((await page1.locator('.nk-downloads li').innerText()).includes('Demo lesson'), 'the downloads list shows the lesson');

  console.log('== playing with no connection');
  await ctx.setOffline(true);
  const page2 = await ctx.newPage();
  page2.on('pageerror', (e) => errors.push(e.message));
  await page2.goto(origin + '/lesson/');
  await page2.waitForSelector('.nk-player video', { timeout: 10000 });
  ok(await page2.locator('.nk-offline-badge').count() === 1, 'the player says it is playing the offline copy');
  const src = await page2.evaluate(() => document.querySelector('.nk-player video').getAttribute('src'));
  ok(src === '/nimikh-offline-media/7/video.mp4', 'the video source is the local copy, not the expired CDN link', src);
  await page2.waitForFunction(() => { const v = document.querySelector('.nk-player video'); return v && v.readyState >= 1 && v.duration > 25; }, null, { timeout: 10000 });
  ok(true, 'the video loads its metadata from the service worker (duration ' + Math.round(await page2.evaluate(() => document.querySelector('.nk-player video').duration)) + ' s)');
  const res = await page2.evaluate(() => fetch('/nimikh-offline-media/7/video.mp4', { headers: { Range: 'bytes=100-199' } }).then((r) => r.arrayBuffer().then((b) => [r.status, b.byteLength, r.headers.get('Content-Range')])));
  ok(res[0] === 206 && res[1] === 100 && /^bytes 100-199\//.test(res[2]), 'byte-range requests are answered with 206 (seeking works)', JSON.stringify(res));
  await page2.evaluate(() => { const v = document.querySelector('.nk-player video'); v.muted = true; return v.play(); });
  await page2.waitForFunction(() => document.querySelector('.nk-player video').currentTime > 1, null, { timeout: 10000 });
  ok(true, 'it plays with the network off');
  await page2.waitForSelector('.nk-sheet', { timeout: 20000 });
  ok(true, 'the in-video question still appears at its timestamp');
  await page2.check('.nk-sheet input[type=radio][value="0"]');
  await page2.click('.nk-sheet .nk-btn');
  await page2.waitForSelector('.nk-feedback');
  await page2.waitForFunction(() => /Answer saved/.test(document.querySelector('.nk-feedback').textContent));
  ok(true, 'offline answers say "saved, we will check it when you are back online"');
  ok(await page2.evaluate(() => JSON.parse(localStorage.getItem('nimikh-attempts-7') || '[]').length) === 1, 'the answer is queued on the device');
  ok(st.attempts.length === 0, 'nothing reached the server while offline');

  console.log('== back online');
  await ctx.setOffline(false);
  await page2.evaluate(() => window.dispatchEvent(new Event('online')));
  await page2.waitForFunction(() => !localStorage.getItem('nimikh-attempts-7'), null, { timeout: 10000 });
  ok(st.attempts.length === 1 && st.attempts[0].selected_index === 0, 'the queued answer was sent to the server for grading', JSON.stringify(st.attempts));

  console.log('== expiry, revocation, removal');
  await page1.bringToFront();
  await page1.evaluate(() => caches.open('nimikh-offline').then((c) => c.put(location.origin + '/nimikh-offline-media/7/license.json', new Response(JSON.stringify({ lesson_id: 7, expires_at: Math.floor(Date.now() / 1000) - 10, title: 'x' })))));
  const expired = await page1.evaluate(() => fetch('/nimikh-offline-media/7/video.mp4').then((r) => r.status));
  ok(expired === 410, 'an expired copy is refused (410)', String(expired));
  ok((await cacheKeys(page1)).filter((k) => k.startsWith('/nimikh-offline-media/7/')).length === 0, 'and its files are deleted');

  await page1.reload(); await page1.waitForSelector('.nk-offline button');
  await page1.click('.nk-offline button');
  await page1.waitForFunction(() => /Available offline/.test(document.querySelector('.nk-offline__text').textContent), null, { timeout: 15000 });
  st.live = [];
  await page1.evaluate(() => window.NimikhOfflineApi.sync());
  ok((await cacheKeys(page1)).filter((k) => k.startsWith('/nimikh-offline-media/7/')).length === 0, 'a copy the server no longer honours is removed on the next online visit');

  st.live = null;
  await page1.reload(); await page1.waitForSelector('.nk-offline button');
  await page1.click('.nk-offline button');
  await page1.waitForFunction(() => /Available offline/.test(document.querySelector('.nk-offline__text').textContent), null, { timeout: 15000 });
  const before = st.releases.length;
  await page1.click('.nk-offline button');
  await page1.waitForFunction(() => /Download for offline/.test(document.querySelector('.nk-offline button').textContent));
  ok(st.releases.length === before + 1 && (await cacheKeys(page1)).filter((k) => k.startsWith('/nimikh-offline-media/7/')).length === 0, 'removing a download deletes the files and frees the server slot');

  console.log('== failures leave nothing behind');
  st.grantStatus = 409;
  await page1.click('.nk-offline button');
  await page1.waitForFunction(() => /limit of downloaded lessons/.test(document.querySelector('.nk-offline__text').textContent));
  ok((await cacheKeys(page1)).filter((k) => k.startsWith('/nimikh-offline-media/7/')).length === 0, 'a refused licence (device/lesson limit) shows the server message and stores nothing');
  st.grantStatus = 200; st.mediaStatus = 500;
  const rel = st.releases.length;
  await page1.click('.nk-offline button');
  await page1.waitForFunction(() => /download failed/.test(document.querySelector('.nk-offline__text').textContent));
  ok((await cacheKeys(page1)).filter((k) => k.startsWith('/nimikh-offline-media/7/')).length === 0 && st.releases.length === rel + 1, 'a failed download is cleaned up and the licence slot is given back');

  ok(errors.length === 0, 'no JavaScript errors' + (errors.length ? ': ' + errors.join('; ') : ''));
  await browser.close(); server.close();
  console.log(`\n${pass + fail} checks, ${fail} failed`);
  process.exit(fail ? 1 : 0);
})().catch((e) => { console.error(e); process.exit(1); });
